// Lane camera staging only. Both peers are real same-origin game windows.
// No game or save belonging to the owner is touched: uishots wipes its own profile.
async function stageDropPair(mode, seat, lostIx, ready) {
  const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
  async function until(fn, label, ms = 25000) {
    const start = Date.now();
    while (Date.now() - start < ms) {
      try { if (fn()) return; } catch (_) {}
      await wait(100);
    }
    throw Error(label);
  }
  const demo = mode === 'demo', pair = new URLSearchParams(location.search).get('pair') || 'cxpadlost0700';
  let host, guest;
  function cleanup() {
    [host,guest].forEach(w => {
      if (!w || w === window || w.closed) return;
      try { w.__gx("if(G&&!G.over&&!G.sim)__endRaid('abandon');netSameStop();"); } catch (_) {}
      try { w.close(); } catch (_) {}
    });
    try { localStorage.removeItem('salvagerun:p2raid'); localStorage.removeItem('salvagerun:p2live'); } catch (_) {}
  }
  window.__j8Cleanup=cleanup;
  window.addEventListener('pagehide',cleanup,{once:true});
  // Only the camera's wiped origin is involved. A failed earlier scene must not
  // leave a heartbeat that prevents the next disposable pair from opening.
  localStorage.removeItem('salvagerun:p2raid');
  localStorage.removeItem('salvagerun:p2live');
  try {
  if (seat === 1) {
    host = window;
    host.__gx("NET.pair='" + pair + "'");
    const opened = demo ? host.__gx('arcadePick()') : host.__net.pick('coop');
    if (opened !== 'opened') throw Error('host did not open a real player 2 window: ' + opened);
    guest = host.__gx('NET.p2win');
  } else {
    guest = window;
    host = window.open(location.pathname + '?netslot=A', 'pad_lost_host', 'popup,width=1952,height=1183');
    if (!host) throw Error('host popup blocked');
    await until(() => host.__net && host.__gx && host.__deploy, 'host fixture did not boot');
    // The main camera page already IS the real p2 window at the requested URL.
    // Return it to the normal opener so the game links it without reloading it.
    const open0 = host.open;
    host.open = function (url) {
      if (!String(url).includes('pair=' + pair) || !String(url).includes('p2=1')) throw Error('wrong player 2 URL');
      return guest;
    };
    try {
      host.__gx("NET.pair='" + pair + "'");
      const opened = demo ? host.__gx('arcadePick()') : host.__net.pick('coop');
      if (opened !== 'opened') throw Error('host did not link the existing p2 window: ' + opened);
    } finally { host.open = open0; }
  }
  await until(() => guest && guest.__net && guest.__gx && guest.__deploy, 'player 2 fixture did not boot');
  await until(() => host.__gx('PLOADED') && guest.__gx('PLOADED'), 'both profiles did not finish loading');
  await until(() => host.__net.state().roster.length === 2 && guest.__net.state().roster.length === 2,
    'both real windows did not link');
  const peers = [host, guest];
  if (demo) {
    await until(() => host.__gx('!!ARCADE.on') && guest.__gx('!!ARCADE.on'), 'both windows did not enter demo');
    if (!host.__gx('arcadeDropIn()')) throw Error('demo host could not ascend');
    if (!guest.__gx('arcadePadAtt(true,true)')) throw Error('demo player 2 could not request entry');
  } else {
    peers.forEach(w => { w.__hubEnter(); w.__gx("document.querySelectorAll('.modal.on').forEach(function(e){e.classList.remove('on');});"); });
    host.__deploy({kit:['gun_carbine', 'bandage'], safe:null, mapIx:0, seed:4242});
  }
  await until(() => peers.every(w => { const g = w.__state(); return g && g.player && !g.over; }),
    'both real windows did not enter a raid');
  peers.forEach(w => w.__gx("keys={}; mouse.down=false; mouse.x=W/2; mouse.y=H/2; G.player.iv=999; G.player.ads=false; G.adsZ=1; G.anchX=undefined; G.anchY=undefined; document.querySelectorAll('.modal.on').forEach(function(e){e.classList.remove('on');});"));
  const p = host.__state().player;
  const home = {x:p.x, y:p.y};
  guest.__net.stand(home.x + 60, home.y + 40);
  const visibleExpr = "(function(){var n=0;(NET.up||[]).forEach(function(u){if(!netUpShown(u)||netUpGone(u)||u.hp<=0)return;var s=w2s(u.x,0,u.y);if(s.x>=0&&s.x<=W&&s.y>=0&&s.y<=H)n++;});return n;})()";
  await until(() => peers.every(w => w.__gx(visibleExpr) > 0), 'the other real pillager is not on screen in both windows');
  const initialVisible=peers.map(w => w.__gx(visibleExpr));

  const partner = seat === 1 ? guest : host;
  setTimeout(cleanup, 90000);
  // the OTHER window drops a frag at its feet; the camera window must get exactly one pile ping, the dropper none
  const dropper = seat === 1 ? guest : host, viewer = seat === 1 ? host : guest;
  viewer.__gx('NET.pings=[];'); dropper.__gx('NET.pings=[];');
  const before = viewer.__gx("(G.containers||[]).filter(function(c){return c.dropped;}).length");
  dropper.__gx("(function(){ G.bag.push('frag'); dropItem(G.bag.lastIndexOf('frag')); return 1; })()");
  await until(() => viewer.__gx("(NET.pings||[]).filter(function(p){return p.pl;}).length") === 1, 'the camera window got no pile ping', 8000);
  await until(() => viewer.__gx("(G.containers||[]).filter(function(c){return c.dropped;}).length") > before, 'the pile did not show in the camera window', 8000);
  await wait(700);
  const report = {mode, seat, realPair: peers.map(w => w.__net.state()), initialVisible,
    viewerPings: viewer.__gx('JSON.stringify(NET.pings)'), dropperPings: dropper.__gx('JSON.stringify(NET.pings||[])')};
  window.__j62Camera = {report, partner};
  return JSON.stringify(report);
  } catch (error) {
    cleanup();
    throw Error(error.message);
  }
}

return await stageDropPair('demo', 1, 1, false);

